{
  "findings": [
    {
      "check_id": "CKV_GCP_26",
      "title": "Ensure that VPC Flow Logs is enabled for every subnet in a VPC Network",
      "resource": "google_compute_subnetwork.data_subnet",
      "severity": "MEDIUM",
      "explanation": "The subnet 'insurance-claims-processing-platform-subnet-data' does not have VPC Flow Logs enabled, limiting the ability to audit and monitor network traffic."
    }
  ],
  "patched_code": "resource \"google_compute_subnetwork\" \"data_subnet\" {\n  name          = \"insurance-claims-processing-platform-subnet-data\"\n  ip_cidr_range = \"10.0.3.0/24\"\n  region        = var.region\n  network       = google_compute_network.claims_vpc.id\n  description   = \"Data subnet for Cloud SQL database\"\n  private_ip_google_access = true\n  log_config {\n    aggregation_interval = \"INTERVAL_5_SEC\"\n    flow_sampling        = 0.5\n    metadata             = \"INCLUDE_ALL_METADATA\"\n  }\n}",
  "fix_summary": "Enabled VPC Flow Logs on the 'data_subnet' subnetwork with a log configuration that includes aggregation interval, flow sampling, and metadata."
}
